const items = $input.all();

// Nom de fichier et format normalisés une seule fois, en amont,
// par « Identifier le service et le prix ».
const serviceInfo =
  $('Identifier le service et le prix').first().json;

const originalFileName = serviceInfo.originalFileName || 'fichier.csv';
const fileFormat = serviceInfo.fileFormat || 'csv';

// Normalisation des noms de colonnes pour les reconnaître
function normalizeHeader(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

const aliases = {
  email: [
    'email', 'emailaddress', 'e-mail', 'mail', 'courriel'
  ],
  name: [
    'name', 'fullname', 'customername', 'firstname',
    'lastname', 'nom', 'nomcomplet', 'client', 'employee'
  ],
  phone: [
    'phone', 'phonenumber', 'mobile', 'mobilenumber',
    'telephone', 'tel', 'contactnumber'
  ],
  city: [
    'city', 'ville', 'town', 'locality'
  ],
  amount: [
    'amount', 'price', 'total', 'value', 'montant',
    'prix', 'revenue', 'sales'
  ],
  date: [
    'date', 'createdat', 'updatedat', 'transactiondate',
    'orderdate'
  ]
};

const normalizedAliases = Object.fromEntries(
  Object.entries(aliases).map(([type, values]) => [
    type,
    values.map(normalizeHeader)
  ])
);

function detectColumns(row) {
  const headers = Object.keys(row);
  const detected = {};

  for (const [type, possibleNames] of Object.entries(normalizedAliases)) {
    detected[type] = headers.find(header =>
      possibleNames.includes(normalizeHeader(header))
    ) || null;
  }

  return detected;
}

function cleanValue(value) {
  if (typeof value !== 'string') return value;

  return value
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

const seenEmails = new Set();
const seenRows = new Set();

return items.map(item => {
  const row = {};

  // Nettoyage générique de toutes les colonnes
  for (const [key, value] of Object.entries(item.json)) {
    row[key] = cleanValue(value);
  }

  const columns = detectColumns(row);

  const email = columns.email
    ? String(row[columns.email] ?? '').trim().toLowerCase()
    : '';

  const duplicateEmail =
    email !== '' && seenEmails.has(email);

  if (email !== '') seenEmails.add(email);

  // Détection de lignes identiques sur les données d'origine
  const rowKey = JSON.stringify(
    Object.keys(row)
      .sort()
      .map(key => [key, row[key]])
  );

  const duplicateRow = seenRows.has(rowKey);
  seenRows.add(rowKey);

  const emailValid =
    columns.email && email !== ''
      ? isValidEmail(email)
      : null;

  const amountValue = columns.amount
    ? String(row[columns.amount] ?? '').trim()
    : '';

  const amountNumber = Number(
    amountValue.replace(/\s/g, '').replace(',', '.')
  );

  const amountValid = columns.amount
    ? amountValue !== '' && Number.isFinite(amountNumber) && amountNumber >= 0
    : null;

  const issues = [];

  if (emailValid === false) issues.push('Email invalide');
  if (duplicateEmail) issues.push('Email en doublon');
  if (duplicateRow) issues.push('Ligne en doublon');
  if (amountValid === false) issues.push('Montant invalide');

  return {
    json: {
      ...row,

      serviceCode: serviceInfo.serviceCode,
      serviceName: serviceInfo.serviceName,

      detected_columns: columns,

      email_valid: emailValid,
      duplicate_email: duplicateEmail,
      duplicate_row: duplicateRow,
      amount_valid: amountValid,

      quality_issues: issues.join('; '),
      quality_status: issues.length ? 'À vérifier' : 'Conforme',

      originalFileName,
      fileFormat
    }
  };
});

const items = $input.all();

const total = items.length;

// 1. Lignes conformes
const conformes = items.filter(
  item => item.json.quality_status === 'Conforme'
).length;

// 2. Lignes à vérifier
const aVerifier = items.filter(
  item => item.json.quality_status === 'À vérifier'
).length;

// 3. Emails invalides
const emailsInvalides = items.filter(
  item => item.json.email_valid === false
).length;

// 4. Montants invalides
const montantsInvalides = items.filter(
  item => item.json.amount_valid === false
).length;

// 5. Emails en doublon
const emailsDoublons = items.filter(
  item => item.json.duplicate_email === true
).length;

// 6. Lignes entièrement dupliquées
const lignesEntierementDupliquees = items.filter(
  item => item.json.duplicate_row === true
).length;

// 7. Détection des doublons potentiels par email et téléphone
const emailsVus = new Set();
const telephonesVus = new Set();

let doublonsPotentiels = 0;

for (const item of items) {
  const row = item.json;

  const email = String(row.email ?? '')
    .trim()
    .toLowerCase();

  // Repérer une colonne de téléphone éventuelle
  const phoneField = Object.keys(row).find(key =>
    /phone|telephone|mobile|tel/i.test(key)
  );

  const telephone = phoneField
    ? String(row[phoneField] ?? '').replace(/\D/g, '')
    : '';

  const emailDejaVu =
    email !== '' && emailsVus.has(email);

  const telephoneDejaVu =
    telephone !== '' && telephonesVus.has(telephone);

  // Une ligne ne compte qu'une fois, même si
  // son email et son téléphone sont tous deux répétés.
  if (emailDejaVu || telephoneDejaVu) {
    doublonsPotentiels++;
  }

  if (email !== '') {
    emailsVus.add(email);
  }

  if (telephone !== '') {
    telephonesVus.add(telephone);
  }
}

// 8. Noms manquants
const nomsManquants = items.filter(
  item => !String(item.json.customer_name ?? '').trim()
).length;

// 9. Villes manquantes
const villesManquantes = items.filter(
  item => !String(item.json.city ?? '').trim()
).length;

// 10. Emails uniques
const emailsUniques = new Set(
  items
    .map(item =>
      String(item.json.email ?? '').trim().toLowerCase()
    )
    .filter(email => email !== '')
).size;

// 11. Rapport qualité
const rapport = [
  {
    indicateur: 'Lignes analysées',
    valeur: total
  },
  {
    indicateur: 'Lignes conformes',
    valeur: conformes
  },
  {
    indicateur: 'Lignes à vérifier',
    valeur: aVerifier
  },
  {
    indicateur: 'Emails invalides',
    valeur: emailsInvalides
  },
  {
    indicateur: 'Emails en doublon',
    valeur: emailsDoublons
  },
  {
    indicateur: 'Emails uniques',
    valeur: emailsUniques
  },
  {
    indicateur: 'Doublons potentiels',
    valeur: doublonsPotentiels
  },
  {
    indicateur: 'Lignes entièrement dupliquées',
    valeur: lignesEntierementDupliquees
  },
  {
    indicateur: 'Montants invalides',
    valeur: montantsInvalides
  },
  {
    indicateur: 'Noms manquants',
    valeur: nomsManquants
  },
  {
    indicateur: 'Villes manquantes',
    valeur: villesManquantes
  },
  {
    indicateur: 'Taux de conformité (%)',
    valeur: total
      ? Math.round((conformes / total) * 1000) / 10
      : 0
  }
];

return rapport.map(ligne => ({
  json: ligne
}));

const items = $input.all();
const rows = items.map(item => item.json);
const originalFileName = rows[0]?.originalFileName || 'fichier.csv';
const MAX_PREVIEW = 1000;

function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[c]);
}

function csvCell(value) {
  let s = String(value ?? '');
  if (/^[\s]*[=+\-@]/.test(s)) s = "'" + s;
  return '"' + s.replace(/"/g, '""') + '"';
}

function isTrue(value) {
  return value === true || String(value).toLowerCase() === 'true';
}

function isFalse(value) {
  return value === false || String(value).toLowerCase() === 'false';
}

function isMissing(value) {
  return value === null || value === undefined || String(value).trim() === '';
}

function statusOf(r) {
  const s = String(r.quality_status || '').toLowerCase().trim();
  if (s === 'conforme' || s === 'ok') return 'ok';
  if (s === 'à vérifier' || s === 'a vérifier') return 'check';
  return '';
}

// Colonnes booléennes : true = bon (GOOD) ou true = problème (BAD)
const GOOD_BOOL = ['email_valid', 'amount_valid'];
const BAD_BOOL = ['duplicate_email', 'duplicate_row'];

const columns = [...new Set(rows.flatMap(r => Object.keys(r)))];

// ---------- CSV ----------
const csv = [
  columns.map(csvCell).join(';'),
  ...rows.map(r => columns.map(c => csvCell(r[c])).join(';'))
].join('\r\n');

const csvBase64 = Buffer.from('\uFEFF' + csv, 'utf8').toString('base64');

// ---------- Statistiques ----------
const totalCells = rows.length * columns.length;
let emptyCells = 0;
for (const r of rows) {
  for (const c of columns) {
    if (isMissing(r[c])) emptyCells++;
  }
}

const completeness = totalCells
  ? Math.round(((totalCells - emptyCells) / totalCells) * 1000) / 10
  : 100;

const quality = {
  conformes: rows.filter(r => statusOf(r) === 'ok').length,
  aVerifier: rows.filter(r => statusOf(r) === 'check').length,
  emailsInvalides: rows.filter(r => isFalse(r.email_valid)).length,
  emailsDoublons: rows.filter(r => isTrue(r.duplicate_email)).length,
  doublonsPotentiels: rows.filter(r => isTrue(r.duplicate_row)).length,
  montantsInvalides: rows.filter(r => isFalse(r.amount_valid)).length,
  nomsManquants: rows.filter(r => isMissing(r.customer_name)).length,
  villesManquantes: rows.filter(r => isMissing(r.city)).length,
  emailsManquants: rows.filter(r => isMissing(r.email)).length
};

quality.tauxConformite = rows.length
  ? Math.round(quality.conformes / rows.length * 1000) / 10
  : 0;

const fileBase = originalFileName.replace(/\.[^.]+$/, '');
const previewRows = rows.slice(0, MAX_PREVIEW);

// ---------- Tableau ----------
const headers = columns
  .map(c => `<th>${esc(c)}<span class="arrow"></span></th>`)
  .join('');

function cell(r, c) {
  const v = r[c];
  if (c === 'quality_status') {
    const st = statusOf(r);
    if (st === 'ok') return `<span class="pill good">✓ ${esc(v)}</span>`;
    if (st === 'check') return `<span class="pill warn">⚠ ${esc(v)}</span>`;
  }
  if (GOOD_BOOL.includes(c)) {
    if (isTrue(v)) return '<span class="pill good">✓ oui</span>';
    if (isFalse(v)) return '<span class="pill bad">✕ non</span>';
  }
  if (BAD_BOOL.includes(c)) {
    if (isTrue(v)) return '<span class="pill bad">● oui</span>';
    if (isFalse(v)) return '<span class="pill mute">non</span>';
  }
  if (isMissing(v)) return '<span class="nil">—</span>';
  return esc(v);
}

const body = previewRows.map(r =>
  `<tr data-s="${statusOf(r)}">${columns.map(c => `<td>${cell(r, c)}</td>`).join('')}</tr>`
).join('');

// ---------- Anomalies ----------
const anomalies = [
  ['Emails invalides', quality.emailsInvalides, '#ff3d9a', '#ff8a5c'],
  ['Emails en doublon', quality.emailsDoublons, '#ff8a5c', '#ffc857'],
  ['Doublons potentiels', quality.doublonsPotentiels, '#ffc857', '#c6ff6b'],
  ['Montants invalides', quality.montantsInvalides, '#7c5cff', '#ff3d9a'],
  ['Noms manquants', quality.nomsManquants, '#22e4ff', '#7c5cff'],
  ['Villes manquantes', quality.villesManquantes, '#2ee6a6', '#22e4ff'],
  ['Emails manquants', quality.emailsManquants, '#c6ff6b', '#2ee6a6']
];

const maxAnomalies = Math.max(1, ...anomalies.map(a => a[1]));
const totalAnomalies = anomalies.reduce((s, a) => s + a[1], 0);

const anomalyBars = anomalies.map(([label, value, c1, c2]) => `
  <div class="chart-row">
    <div class="chart-label"><span>${esc(label)}</span><strong>${value}</strong></div>
    <div class="chart-track">
      <div class="chart-fill" data-w="${Math.max(value ? 4 : 0, value / maxAnomalies * 100)}"
        style="background:linear-gradient(90deg,${c1},${c2});box-shadow:0 0 14px ${c1}88"></div>
    </div>
  </div>`).join('');

// ---------- Anneaux SVG ----------
function ring(pct, id, c1, c2) {
  return `<svg viewBox="0 0 160 160" class="ring" aria-hidden="true">
    <defs>
      <linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/>
      </linearGradient>
    </defs>
    <circle cx="80" cy="80" r="68" class="ring-bg" pathLength="100"/>
    <circle cx="80" cy="80" r="68" class="ring-fg" pathLength="100"
      stroke="url(#${id})" data-v="${pct}" style="color:${c1}"/>
  </svg>`;
}

const fr = n => Number(n).toLocaleString('fr-FR');

