.chart-description { color:var(--muted); font-size:14px; line-height:1.6; margin:0 0 24px; }

.donut-area { display:flex; align-items:center; justify-content:center; flex-wrap:wrap; gap:26px; }
.mini { position:relative; width:170px; display:grid; place-items:center; flex-shrink:0; }
.mini .ring { max-width:170px; }
.mini .ring-center strong { font-size:30px; letter-spacing:-1px; }
.mini .ring-center span { font-size:11px; }

.legend { display:grid; gap:14px; min-width:150px; }
.legend-item { display:flex; align-items:center; gap:10px; font-size:14px; }
.legend-dot { width:11px;height:11px;border-radius:4px;flex-shrink:0; }
.legend-item strong { margin-left:auto; padding-left:14px; }

.chart-row { margin:18px 0; }
.chart-label { display:flex; justify-content:space-between; gap:12px; font-size:14px; margin-bottom:9px; color:#e4defa; }
.chart-label strong { color:#fff; }
.chart-track { height:10px; border-radius:99px; overflow:hidden; background:rgba(255,255,255,.08); }
.chart-fill { height:100%; width:0; border-radius:99px; transition:width 1.6s cubic-bezier(.2,.8,.2,1); }

.quality-note {
  margin-top:22px; padding:14px 16px; border-radius:14px;
  background:rgba(124,92,255,.14); border:1px solid rgba(124,92,255,.25);
  color:#c9c1ee; font-size:13px; line-height:1.6;
}
.all-clear { color:#8bf5cf; background:rgba(46,230,166,.1); border-color:rgba(46,230,166,.3); }

/* ---------- Tableau ---------- */
.panel { padding:30px; margin-top:24px; }
.top { display:flex; flex-wrap:wrap; gap:16px; align-items:center; justify-content:space-between; margin-bottom:16px; }
h2.title { margin:0; font-family:var(--display); font-size:26px; font-weight:700; }

.search {
  width:min(400px,100%); padding:14px 18px; border-radius:16px;
  color:var(--text); border:1px solid var(--glass-b); outline:none;
  font:500 14px var(--body); background:rgba(255,255,255,.06);
  transition:border-color .2s, box-shadow .2s;
}
.search::placeholder { color:#7d77a3; }
.search:focus { border-color:var(--pink); box-shadow:0 0 0 4px rgba(255,61,154,.2); }

.chips { display:flex; gap:10px; flex-wrap:wrap; margin-bottom:18px; }
.chip {
  cursor:pointer; padding:9px 18px; border-radius:999px;
  border:1px solid var(--glass-b); background:rgba(255,255,255,.05);
  color:var(--muted); font:600 13px var(--body); transition:all .2s;
}
.chip:hover { color:#fff; border-color:rgba(255,255,255,.35); }
.chip[aria-pressed="true"] {
  color:#1a0b2e; border-color:transparent;
  background:linear-gradient(120deg,var(--gold),var(--pink));
  box-shadow:0 6px 22px rgba(255,61,154,.4);
}

.wrap { overflow:auto; max-height:62vh; border-radius:18px; border:1px solid var(--glass-b); background:rgba(5,3,15,.35); }
.wrap::-webkit-scrollbar { width:10px; height:10px; }
.wrap::-webkit-scrollbar-thumb { background:linear-gradient(var(--pink),var(--violet)); border-radius:99px; }

table { border-collapse:collapse; width:100%; font-size:13.5px; }
th {
  position:sticky; top:0; z-index:2; cursor:pointer; user-select:none;
  text-align:left; padding:16px 18px; white-space:nowrap;
  font-weight:700; font-size:12px; letter-spacing:.4px;
  color:#e9defd; background:#171033;
  border-bottom:2px solid transparent;
  border-image:linear-gradient(90deg,var(--pink),var(--gold),var(--cyan)) 1;
}
th:hover { color:var(--gold); }
th .arrow { display:inline-block; width:14px; margin-left:6px; color:var(--cyan); }
td { padding:13px 18px; white-space:nowrap; border-top:1px solid rgba(255,255,255,.06); color:#e4defa; }
tbody tr { transition:background .2s; }
tbody tr:nth-child(even) { background:rgba(255,255,255,.028); }
tbody tr:hover { background:linear-gradient(90deg,rgba(255,61,154,.16),rgba(124,92,255,.16)); }
.nil { color:#5f5a86; }

.pill { display:inline-block; padding:4px 12px; border-radius:999px; font-size:12px; font-weight:700; }
.pill.good { color:#7cf3c8; background:rgba(46,230,166,.13); border:1px solid rgba(46,230,166,.35); }
.pill.warn { color:#ffd98a; background:rgba(255,200,87,.13); border:1px solid rgba(255,200,87,.38); }
.pill.bad  { color:#ff8fc0; background:rgba(255,61,154,.14); border:1px solid rgba(255,61,154,.4); }
.pill.mute { color:#7d77a3; background:rgba(255,255,255,.05); border:1px solid rgba(255,255,255,.1); }

.foot { display:flex; flex-wrap:wrap; justify-content:space-between; gap:8px; margin-top:16px; color:var(--muted); font-size:13px; }
.empty { display:none; text-align:center; padding:44px; color:var(--muted); }

@media (max-width:820px) {
  .hero { grid-template-columns:1fr; padding:40px 26px; text-align:center; }
  .sub { margin-inline:auto; }
  .ring-wrap { order:-1; max-width:240px; margin:0 auto; }
}
@media (max-width:600px) {
  body { padding:16px 12px 40px; }
  .panel, .chart-card { padding:20px; }
}
@media (prefers-reduced-motion:reduce) {
  *, *::before { animation:none !important; transition:none !important; }
}
