<script>
const encoded = "${csvBase64}";
const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

// ---------- Étoiles scintillantes ----------
(function () {
  if (reduced) return;
  const cv = document.getElementById('stars');
  const ctx = cv.getContext('2d');
  let w, h, stars = [];
  function resize() {
    w = cv.width = innerWidth; h = cv.height = innerHeight;
    stars = Array.from({length: Math.min(110, Math.floor(w * h / 14000))}, () => ({
      x: Math.random() * w, y: Math.random() * h,
      r: Math.random() * 1.4 + .3, p: Math.random() * 6.28, s: Math.random() * .02 + .005
    }));
  }
  resize(); addEventListener('resize', resize);
  (function draw() {
    ctx.clearRect(0, 0, w, h);
    for (const s of stars) {
      s.p += s.s;
      ctx.globalAlpha = .25 + .75 * Math.abs(Math.sin(s.p));
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, 6.283); ctx.fill();
    }
    requestAnimationFrame(draw);
  })();
})();

// ---------- Confettis ----------
function confetti() {
  if (reduced) return;
  const cv = document.getElementById('confetti');
  const ctx = cv.getContext('2d');
  cv.width = innerWidth; cv.height = innerHeight;
  const colors = ['#ff3d9a', '#ffc857', '#22e4ff', '#2ee6a6', '#7c5cff', '#ffffff'];
  const ps = Array.from({length: 150}, () => ({
    x: innerWidth / 2, y: innerHeight * .35,
    vx: (Math.random() - .5) * 18, vy: Math.random() * -16 - 4,
    s: Math.random() * 8 + 4, c: colors[Math.floor(Math.random() * colors.length)],
    a: Math.random() * 6.28, va: (Math.random() - .5) * .4, life: 1
  }));
  (function frame() {
    ctx.clearRect(0, 0, cv.width, cv.height);
    let alive = false;
    for (const p of ps) {
      p.vy += .38; p.x += p.vx; p.y += p.vy; p.a += p.va; p.vx *= .99; p.life -= .006;
      if (p.life > 0 && p.y < cv.height + 20) {
        alive = true;
        ctx.save(); ctx.globalAlpha = Math.max(p.life, 0);
        ctx.translate(p.x, p.y); ctx.rotate(p.a);
        ctx.fillStyle = p.c; ctx.fillRect(-p.s / 2, -p.s / 4, p.s, p.s / 2);
        ctx.restore();
      }
    }
    if (alive) requestAnimationFrame(frame); else ctx.clearRect(0, 0, cv.width, cv.height);
  })();
}

// ---------- Téléchargement CSV ----------
document.getElementById('download').onclick = () => {
  const raw = atob(encoded);
  const bytes = Uint8Array.from(raw, c => c.charCodeAt(0));
  const blob = new Blob([bytes], {type: 'text/csv;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = ${JSON.stringify(fileBase + '_nettoye.csv')};
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
  confetti();
};

// ---------- Halo qui suit la souris ----------
document.querySelectorAll('.glass').forEach(el => {
  el.addEventListener('pointermove', e => {
    const r = el.getBoundingClientRect();
    el.style.setProperty('--mx', (e.clientX - r.left) + 'px');
    el.style.setProperty('--my', (e.clientY - r.top) + 'px');
  });
});

// ---------- Compteurs animés ----------
document.querySelectorAll('[data-to]').forEach(el => {
  const to = parseFloat(el.dataset.to) || 0;
  const dec = +(el.dataset.dec || 0);
  const suf = el.dataset.suf || '';
  const t0 = performance.now();
  const dur = reduced ? 1 : 1800;
  (function step(t) {
    const p = Math.min((t - t0) / dur, 1);
    const e = 1 - Math.pow(1 - p, 4);
    el.textContent = (to * e).toLocaleString('fr-FR', {
      minimumFractionDigits: dec, maximumFractionDigits: dec
    }) + suf;
    if (p < 1) requestAnimationFrame(step);
  })(t0);
});

// ---------- Anneaux et barres ----------
setTimeout(() => {
  document.querySelectorAll('.ring-fg').forEach(c => {
    c.style.strokeDasharray = Math.min(100, +c.dataset.v) + ' 100';
  });
  document.querySelectorAll('.chart-fill').forEach(b => { b.style.width = b.dataset.w + '%'; });
  const b = document.getElementById('bar');
  if (b) b.style.width = b.dataset.w + '%';
}, 300);

// Célébration si le fichier est très propre
if (${quality.tauxConformite} >= 90) setTimeout(confetti, 900);

// ---------- Recherche + filtres ----------
const search = document.getElementById('search');
const tbody = document.getElementById('data');
const countEl = document.getElementById('count');
const emptyEl = document.getElementById('empty');
let statusFilter = '';

function filter() {
  const q = search.value.toLowerCase();
  const trs = [...tbody.rows];
  let n = 0;
  trs.forEach(tr => {
    const okText = tr.textContent.toLowerCase().includes(q);
    const okStatus = !statusFilter || tr.dataset.s === statusFilter;
    tr.hidden = !(okText && okStatus);
    if (!tr.hidden) n++;
  });
  emptyEl.style.display = n ? 'none' : 'block';
  countEl.textContent = n + ' ligne(s) affichée(s) sur ' + trs.length;
}

search.addEventListener('input', filter);

document.querySelectorAll('.chip').forEach(chip => {
  chip.addEventListener('click', () => {
    statusFilter = chip.dataset.f;
    document.querySelectorAll('.chip').forEach(c => c.setAttribute('aria-pressed', c === chip ? 'true' : 'false'));
    filter();
  });
});
filter();

// ---------- Tri par colonne ----------
let sortIdx = -1;
let asc = true;

document.querySelectorAll('th').forEach((th, i) => {
  th.addEventListener('click', () => {
    asc = sortIdx === i ? !asc : true;
    sortIdx = i;

    document.querySelectorAll('th .arrow').forEach(a => a.textContent = '');
    th.querySelector('.arrow').textContent = asc ? '▲' : '▼';

    const trs = [...tbody.rows];

    trs.sort((a, b) => {
      const x = a.cells[i].textContent.trim();
      const y = b.cells[i].textContent.trim();
      const nx = parseFloat(x.replace(',', '.'));
      const ny = parseFloat(y.replace(',', '.'));

      const bothNum =
        !isNaN(nx) && !isNaN(ny) &&
        /^-?[\\d\\s.,]+$/.test(x) &&
        /^-?[\\d\\s.,]+$/.test(y);

      const result = bothNum
        ? nx - ny
        : x.localeCompare(y, 'fr', {numeric: true});

      return asc ? result : -result;
    });

    trs.forEach(tr => tbody.appendChild(tr));
  });
});
</script>

</body>
