// ============================================================
// DataClean Pro — Identification du service ET du format fichier
// ============================================================

// ⚙️ ID du champ Tally « format du fichier ».
// Laisser vide ('') pour la détection automatique (balayage des champs).
const FORMAT_FIELD_ID = '';

// ⚙️ Champ Tally contenant l'URL du fichier téléversé.
const FILE_URL_FIELD_ID = 'question_ZGkd5z';

// ⚙️ Champs Tally qui ne peuvent jamais désigner un format de fichier.
// Ils sont ignorés par la détection automatique.
const NON_FORMAT_FIELDS = [
  'question_N4NA5B', // type de service
  'question_x0bdxy', // adresse e-mail
  'question_2bd48L', // nom du client
  'question_qYQbZY'  // instructions libres
];

// ⚙️ Source prioritaire pour le format :
//   'tally'     → champ du formulaire Tally
//   'extension' → extension de l'URL du fichier
// L'autre source sert toujours de secours. En cas de désaccord,
// l'extension du fichier est retenue (le fichier physique ne ment pas)
// et un avertissement est écrit dans `fileFormatWarning`.
const FORMAT_PRIORITY = 'tally';

// Formats acceptés → opération « Extract from File » correspondante
const EXTRACT_OPERATIONS = {
  csv: 'csv',
  tsv: 'csv',
  txt: 'text',
  json: 'fromJson',
  xlsx: 'xlsx',
  xls: 'xls',
  ods: 'ods'
};

const EXTENSION_TO_FORMAT = {
  csv: 'csv',
  tsv: 'tsv',
  tab: 'tsv',
  txt: 'txt',
  text: 'txt',
  json: 'json',
  xlsx: 'xlsx',
  xls: 'xls',
  ods: 'ods'
};

const FORMAT_ALIASES = {
  csv: 'csv',
  'text/csv': 'csv',
  'application/csv': 'csv',
  tsv: 'tsv',
  tab: 'tsv',
  'text/tab-separated-values': 'tsv',
  txt: 'txt',
  text: 'txt',
  texte: 'txt',
  'text/plain': 'txt',
  json: 'json',
  'application/json': 'json',
  xlsx: 'xlsx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  xls: 'xls',
  'application/vnd.ms-excel': 'xls',
  ods: 'ods',
  'application/vnd.oasis.opendocument.spreadsheet': 'ods'
};

function detectFormatFromValue(value) {
  const token = String(value ?? '').trim().toLowerCase();
  if (!token) return null;
  if (FORMAT_ALIASES[token]) return FORMAT_ALIASES[token];

  // Valeurs du type « Fichier CSV », « CSV (.csv) », « feuille xlsx »
  const match = token.match(/\b(xlsx|xls|ods|csv|tsv|txt|texte|text|json)\b/);
  return match ? EXTENSION_TO_FORMAT[match[1]] || null : null;
}

function extractUrl(raw) {
  if (!raw) return '';
  if (typeof raw === 'string') return raw;
  if (Array.isArray(raw)) {
    for (const entry of raw) {
      const url = extractUrl(entry);
      if (url) return url;
    }
    return '';
  }
  if (typeof raw === 'object') {
    if (typeof raw.url === 'string' && raw.url) return raw.url;
    if (typeof raw.value === 'string' && raw.value) return raw.value;
    if (raw.value !== undefined) return extractUrl(raw.value);
  }
  return '';
}

function extractText(raw) {
  if (raw === null || raw === undefined) return '';
  if (typeof raw === 'string') return raw;
  if (Array.isArray(raw)) {
    return raw.map(extractText).filter(Boolean).join(' ');
  }
  if (typeof raw === 'object') {
    if (raw.value !== undefined) return extractText(raw.value);
    if (raw.name !== undefined) return extractText(raw.name);
  }
  return '';
}

function resolveUrlFormat(json) {
  const url = extractUrl(json[FILE_URL_FIELD_ID]);
  if (!url) return null;
  const path = url.split('?')[0].split('#')[0];
  const match = path.match(/\.([a-z0-9]+)$/i);
  if (!match) return null;
  return EXTENSION_TO_FORMAT[match[1].toLowerCase()] || null;
}

function resolveTallyFormat(json) {
  if (FORMAT_FIELD_ID) {
    const explicit = detectFormatFromValue(extractText(json[FORMAT_FIELD_ID]));
    if (explicit) return explicit;
  }

  for (const key of Object.keys(json)) {
    if (!key.startsWith('question_')) continue;
    if (key === FILE_URL_FIELD_ID) continue;
    if (NON_FORMAT_FIELDS.includes(key)) continue;
    const value = extractText(json[key]).trim();
    if (!value || value.length > 40) continue;
    const detected = detectFormatFromValue(value);
    if (detected) return detected;
  }

  return null;
}

function resolveFileName(json) {
  const url = extractUrl(json[FILE_URL_FIELD_ID]);
  const path = url.split('?')[0].split('#')[0];
  const last = path.split('/').pop() || '';
  let name = last;
  try {
    name = decodeURIComponent(last);
  } catch (error) {
    name = last;
  }
  return name || 'fichier.csv';
