const items = $input.all();

const technicalFields = new Set([
  'customerid',
  'emailvalid',
  'duplicateemail',
  'duplicaterow',
  'amountvalid',
  'qualityissues',
  'qualitystatus',
  'originalfilename',
  'sourcename',
  'deduplicationstatus',
  'duplicatepotential',
  'duplicatereason',
  'qualityscore',
  'outputcategory'
]);

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizePhone(value) {
  return String(value ?? '').replace(/\D/g, '');
}

function normalizeFieldName(key) {
  return normalizeText(key).replace(/[^a-z0-9]/g, '');
}

function normalizeValue(key, value) {
  if (value === null || value === undefined) return '';

  const field = normalizeFieldName(key);

  if (
    field.includes('phone') ||
    field.includes('telephone') ||
    field.includes('mobile') ||
    field === 'tel' ||
    field === 'portable'
  ) {
    return normalizePhone(value);
  }

  return typeof value === 'string'
    ? normalizeText(value)
    : String(value);
}

// Détecter automatiquement les colonnes e-mail
function getEmail(row) {
  const emailKey = Object.keys(row).find(key => {
    const field = normalizeFieldName(key);

    return [
      'email',
      'emailaddress',
      'mail',
      'courriel',
      'adresseelectronique'
    ].includes(field);
  });

  return emailKey
    ? normalizeText(row[emailKey])
    : '';
}

// Détecter automatiquement les colonnes téléphone
function getPhone(row) {
  for (const key of Object.keys(row)) {
    const field = normalizeFieldName(key);

    if (
      field.includes('phone') ||
      field.includes('telephone') ||
      field.includes('mobile') ||
      field === 'tel' ||
      field === 'portable'
    ) {
      const phone = normalizePhone(row[key]);

      if (phone) return phone;
    }
  }

  return '';
}

// Construire une clé de comparaison avec les colonnes d'origine
function getExactKey(row) {
  return Object.keys(row)
    .filter(key => !technicalFields.has(normalizeFieldName(key)))
    .sort()
    .map(key =>
      `${normalizeFieldName(key)}:${normalizeValue(key, row[key])}`
    )
    .join('|');
}

// Normaliser les téléphones sans modifier les autres colonnes
const seenExact = new Set();
const uniqueRows = [];

for (const item of items) {
  const row = { ...item.json };

  for (const key of Object.keys(row)) {
    const field = normalizeFieldName(key);

    if (
      field.includes('phone') ||
      field.includes('telephone') ||
      field.includes('mobile') ||
      field === 'tel' ||
      field === 'portable'
    ) {
      row[key] = normalizePhone(row[key]);
    }
  }

  // Supprimer les doublons exacts
  const exactKey = getExactKey(row);

  if (seenExact.has(exactKey)) {
    continue;
  }

  seenExact.add(exactKey);

  row.deduplication_status = 'Conservé';
  row.duplicate_potential = false;
  row.duplicate_reason = '';

  uniqueRows.push(row);
}

// Détecter les contacts déjà rencontrés
const reviewRows = [];

for (let i = 0; i < uniqueRows.length; i++) {
  const current = uniqueRows[i];

  const currentEmail = getEmail(current);
  const currentPhone = getPhone(current);

  const reasons = [];

  // Comparer avec les lignes précédentes
  for (let j = 0; j < i; j++) {
    const previous = uniqueRows[j];

    const previousEmail = getEmail(previous);
    const previousPhone = getPhone(previous);

    const sameEmail =
      currentEmail !== '' &&
      currentEmail === previousEmail;

    const samePhone =
      currentPhone !== '' &&
      previousPhone !== '' &&
      currentPhone === previousPhone;

    if (sameEmail) {
      reasons.push('Adresse e-mail déjà utilisée');
    }

    if (samePhone) {
      reasons.push('Numéro de téléphone déjà utilisé');
    }

    if (reasons.length > 0) break;
  }

  if (reasons.length > 0) {
    current.deduplication_status = 'À vérifier';
    current.duplicate_potential = true;
    current.duplicate_reason = reasons.join('; ');

    reviewRows.push(current);
  }
}

// Tous les enregistrements uniques restent dans le fichier nettoyé.
// Les doublons potentiels sont également copiés dans le fichier de vérification.
return [
  ...uniqueRows.map(row => ({
    json: {
      ...row,
      output_category: 'NETTOYE'
    }
  })),

  ...reviewRows.map(row => ({
    json: {
      ...row,
      output_category: 'A_VERIFIER'
    }
  }))
];

