// ============================================================
// DataClean Pro — Normalisation des lignes extraites
// « Extract from File » renvoie des structures différentes selon
// le format : lignes (csv/xlsx/xls/ods), objet/tableau (json) ou
// texte brut (txt). Ce nœud garantit une seule forme en sortie :
// un item = une ligne = un objet de colonnes.
// ============================================================

const meta = $('Identifier le service et le prix').first().json;
const format = meta.fileFormat || 'csv';
const items = $input.all();

function toRow(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object' && !Array.isArray(value)) return value;
  return { valeur: value };
}

function splitLines(text) {
  return String(text ?? '')
    .replace(/^\uFEFF/, '')
    .split(/\r\n|\r|\n/)
    .filter(line => line.trim() !== '');
}

function detectDelimiter(line) {
  const candidates = ['\t', ';', ',', '|'];
  let best = ',';
  let bestCount = 0;

  for (const candidate of candidates) {
    const count = line.split(candidate).length - 1;
    if (count > bestCount) {
      bestCount = count;
      best = candidate;
    }
  }

  return best;
}

function cleanCell(value) {
  return String(value ?? '')
    .trim()
    .replace(/^"(.*)"$/, '$1')
    .trim();
}

function parseDelimited(text) {
  const lines = splitLines(text);
  if (!lines.length) return [];

  const delimiter = detectDelimiter(lines[0]);
  const headers = lines[0].split(delimiter).map(cleanCell);

  return lines.slice(1).map(line => {
    const cells = line.split(delimiter);
    const row = {};

    headers.forEach((header, index) => {
      row[header || `colonne_${index + 1}`] = cleanCell(cells[index]);
    });

    return row;
  });
}

function unwrapSingleArray(payload) {
  if (!Array.isArray(payload) || payload.length !== 1) return payload;

  const first = payload[0];
  if (!first || typeof first !== 'object' || Array.isArray(first)) {
    return payload;
  }

  const keys = Object.keys(first);
  if (keys.length === 1 && Array.isArray(first[keys[0]])) {
    return first[keys[0]];
  }

  return payload;
}

let rows = [];

if (format === 'json') {
  const payload =
    items.length === 1 ? items[0].json.data : items.map(item => item.json.data);

  const list = unwrapSingleArray(Array.isArray(payload) ? payload : [payload]);
  rows = list.map(toRow).filter(Boolean);
} else if (format === 'txt') {
  const text = items.map(item => item.json.data ?? '').join('\n');
  rows = parseDelimited(text);
} else {
  rows = items
    .map(item => item.json)
    .filter(row => row && typeof row === 'object' && !Array.isArray(row));
}

if (!rows.length) {
  throw new Error(
    `Aucune ligne exploitable dans « ${meta.originalFileName} » ` +
      `(format détecté : ${format}). Vérifiez le fichier ou le format déclaré.`
  );
}

return rows.map(row => ({ json: row }));
